-- Maelstrom1038: row3 is the independent UPDATE wave producer.
-- Retain stage2/no-nearby-Gethxun gates and its original seven summons.
-- Interaction row2 must not call this independent event as a LINK.
SET @maelstrom_wave_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
